export const NETHER_DREAD_LORD_V2_DEF=Object.freeze({grid:NETHER_DREAD_LORD_V2_GRID,materials:NETHER_DREAD_LORD_V2_MATERIALS,parts:PARTS,
 animate({frame=0,now=0,pose='idle',reducedMotion=false,charging=false,netherPhase=1,unsealed=false,purged=false,soulFireVisible=true,rearAuraVisible=true}={}){
 if(pose==='dead')return {partStates:{hideParts:true},effects:[]};
 const open=netherPhase===2||unsealed; const charged=charging||pose==='charge';
 const tick=reducedMotion?0:Math.floor(now>0?now/(charged?120:180):frame);const f=((tick%12)+12)%12;const flame=((tick%8)+8)%8;
 const armCycle=[0,1,2,3,4,5,6,7];
 const armFrame=reducedMotion?0:charged?3:pose==='attack'?4:armCycle[((Math.floor(tick/2)%8)+8)%8];
 return {partStates:{rightArm:{frame:armFrame},soulAuraRear:{frame:1+(reducedMotion?0:flame),visible:open&&rearAuraVisible},cloakLeft:{frame:(open?12:0)+f},cloakRight:{frame:(open?12:0)+f},soulFlame:{frame:reducedMotion?0:flame,visible:soulFireVisible}},effects:[]};
 }});
